import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.Bd7kzaCy.js";const h=JSON.parse('{"title":"附录B　编号体系与术语总表","description":"","frontmatter":{"title":"附录B　编号体系与术语总表"},"headers":[],"relativePath":"theory/appendix-b.md","filePath":"theory/appendix-b.md"}'),p={name:"theory/appendix-b.md"};function i(n,t,o,S,E,s){return r(),e("div",null,[...t[0]||(t[0]=[a('<div class="theory-source"><p><a id="part_18"></a></p><h1 id="part-title-18" tabindex="-1">附录B　编号体系与术语总表 <a class="header-anchor" href="#part-title-18" aria-label="Permalink to &quot;附录B　编号体系与术语总表 {#part-title-18}&quot;">​</a></h1><p>全书共使用下列编号体系。本表只作导航索引，各体系的定义、合同与使用边界以正文相应部分为准。</p><table tabindex="0"><thead><tr><th>前缀</th><th>含义</th><th>数量</th><th>定义所在</th></tr></thead><tbody><tr><td>D0-D3</td><td>定义层:结构对象、基本状态词、有效反馈、尺度变换</td><td>4</td><td>第三部分</td></tr><tr><td>U01-U11</td><td>通用结构原语</td><td>11</td><td>第三部分</td></tr><tr><td>G1-G4</td><td>经验问题族（经 G-instance 建立具体检验）</td><td>4</td><td>第四部分</td></tr><tr><td>法1—法3</td><td>共同方法约束：任务与表示、材料身份与支持范围、事实价值与行动资格</td><td>3</td><td>第四部分及附录C</td></tr><tr><td>F1-F6</td><td>条件形式命题：任务恢复、闭合、动作共同可行性、组合保持、误差传播与任务族精化</td><td>6</td><td>第四部分及附录C</td></tr><tr><td>E1-E5</td><td>认识论约束</td><td>5</td><td>第四部分</td></tr><tr><td>C1-C12</td><td>结果合同、机制命题与程序桥接</td><td>12</td><td>第四部分</td></tr><tr><td>A/X/T/O/C/R/I/N/J</td><td>九轴尺度画像 SP 的九个轴</td><td>9</td><td>第五部分</td></tr><tr><td>M01-M09</td><td>尺度变换算子</td><td>9</td><td>第五部分</td></tr><tr><td>CM-*</td><td>条件机制:FEEDBACK、LEARNING、MAINTENANCE、LOAD、PHASE、SELECTION</td><td>6</td><td>第六部分</td></tr><tr><td>H1-H6</td><td>人类领域条款</td><td>6</td><td>第七部分</td></tr><tr><td>GC/GS/GE/CV/RS/IS/IM/IB</td><td>三组不可混装的强类型(生成条件/主体/事件,承接载体,责任主体,失稳来源/机制/行为)</td><td>8</td><td>第七部分</td></tr><tr><td>HV01-HV11</td><td>人类变量统一接口(完整接口卡见附录 A)</td><td>11</td><td>第七部分</td></tr><tr><td>S0-S6、X0</td><td>人类状态原型与有序退场路径</td><td>7+1</td><td>第八部分</td></tr><tr><td>IG1-IG7</td><td>七闸:唯一主流程</td><td>7</td><td>第十三部分</td></tr><tr><td>SJ1-SJ8</td><td>强判断八件套</td><td>8</td><td>第十三部分</td></tr><tr><td>L1-L3</td><td>诊断档位</td><td>3</td><td>第十三部分</td></tr><tr><td>TOOL-*</td><td>六项正式工具(EVIDENCE-LEDGER、OPEN-ASSERTION、CLAIM-VALIDATION、FORECAST-REGISTRY、STRESS-TEST、AI-BOUNDARY)</td><td>6</td><td>第十三部分</td></tr><tr><td>N1-N5</td><td>规范选择的运行时前提登记</td><td>5</td><td>第十四部分</td></tr><tr><td>O1-O4</td><td>有限授权程序</td><td>4</td><td>第十四部分</td></tr><tr><td>PF-1-PF-10</td><td>规范选择与选择记录的接口</td><td>10</td><td>第十四部分</td></tr><tr><td>T0-T4</td><td>干涉层级</td><td>5</td><td>第十五部分</td></tr><tr><td>APP-*</td><td>应用模块(REL、FAM、ORG、PLT、INS、OPI、SPC、EMG、ULS)</td><td>9</td><td>第十五部分</td></tr><tr><td>GOV-01-GOV-24</td><td>治理条款</td><td>24</td><td>第十六部分</td></tr></tbody></table><p>另有若干贯穿全书的记号:S*=&lt;B,X,R,I,T,SP,K&gt; 为 D0 候选对象合同的七个字段(边界、状态变量、关系或转移约束、接口、时间窗、尺度剖面、同一性判据);N0 为零模型;K*/F* 为修复的目标同一性判据与功能判据;G-instance、H-instance 为经验问题族与人类条款的具体检验实例。均以正文首次定义处为准。</p><p>F1—F6是形式命题编号；单独的F及F*按局部定义可以分别表示动力更新、功能判据或修复目标，不凭字母相同推定同一对象。G3只检验给定当前表示之外的历史条件增量；载体介导的学习、累积、持续效应与跨期再生产依各自机制合同检验，不以G3获得正向支持作为共同前提。</p></div>',1)])])}const l=d(p,[["render",i]]);export{h as __pageData,l as default};
